using FreshFoundation;
namespace RiseWorkshopDesktop;
internal sealed class EquipmentDraftForm : Form
{
    internal static string L(string en,string zh)=>UiLanguage.Current=="zh-CN"?zh:en;
    private readonly ComboBox[] jewels=new ComboBox[3],skills=new ComboBox[2];
    private readonly EquipmentDraft opened;
    private readonly DirectoryEditor editor;
    internal EquipmentDraftForm(DirectoryEditor editor,int index,CatalogProviderNames names)
    {
        this.editor=editor;opened=editor.Domain!.ReadEquipmentDraft(index);Text=L("Equipment draft","装备草稿");Size=new(920,650);MinimumSize=new(780,580);StartPosition=FormStartPosition.CenterParent;Font=new("Microsoft YaHei UI",9.5f);
        var root=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new(16)};var shell=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};shell.ColumnStyles.Add(new(SizeType.Percent,100));shell.RowStyles.Add(new(SizeType.Percent,100));shell.RowStyles.Add(new(SizeType.AutoSize));Controls.Add(shell);shell.Controls.Add(root,0,0);
        root.Controls.Add(new Label(){AutoSize=true,Text=$"{L("Record","记录")} {index} · {UiLanguage.T(PresentationRows.TypeName(opened.Type))} · ID {opened.Id}"});
        root.Controls.Add(new Label(){AutoSize=true,MaximumSize=new(820,0),Text=L("Socket capacities are unknown. Only clear or restore the original same-position reference. Jewel stock and native-game effects are unverified.","槽容量未知。仅可清除或恢复该记录原位置的引用；珠库存变化及游戏效果尚未验证。")});
        var tip=new ToolTip();Disposed+=(_,_)=>tip.Dispose();
        for(int i=0;i<3;i++){int position=i;var row=new FlowLayoutPanel(){AutoSize=true,WrapContents=false};row.Controls.Add(new Label(){AutoSize=true,Text=L("Decoration position ","装饰珠位置 ")+(i+1)});var choice=jewels[i]=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDownList,Width=560,Enabled=opened.Decorations is not null};choice.FormattingEnabled=true;choice.Format+=(_,e)=>{if(e.ListItem is uint id)e.Value=id==0?L("None (0)","无 (0)"):$"ID {id} · "+names.GameLabel(GameCatalogKind.Decoration,id);};choice.Items.Add(0u);if(opened.OriginalDecorations is not null&&opened.OriginalDecorations[i]!=0)choice.Items.Add(opened.OriginalDecorations[i]);choice.SelectedItem=opened.Decorations?[i]??0u;choice.SelectedIndexChanged+=(_,_)=>{if(choice.SelectedItem is uint id)tip.SetToolTip(choice,names.Describe(GameCatalogKind.Decoration,id));};tip.SetToolTip(choice,names.Describe(GameCatalogKind.Decoration,opened.Decorations?[i]??0));row.Controls.Add(choice);root.Controls.Add(row);}
        if(opened.DecorationIssue is not null)root.Controls.Add(new Label(){AutoSize=true,Text=L("Decoration editing unavailable: ","装饰珠编辑不可用：")+opened.DecorationIssue});
        var clear=new Button(){AutoSize=true,Text=L("Clear all three in draft","草稿中清除全部三项"),Enabled=opened.Decorations is not null};clear.Click+=(_,_)=>{foreach(var c in jewels)c.SelectedItem=0u;};root.Controls.Add(clear);
        if(opened.Type==3){root.Controls.Add(new Label(){AutoSize=true,MaximumSize=new(700,0),Text=L("Filter skills by name / ID. Selection stays available. Hover a choice for full name and source.","按名称 / ID 筛选技能，保留当前选择。悬停选项查看完整名称及来源。")});for(int i=0;i<2;i++){int ordinal=i;var line=new FlowLayoutPanel(){AutoSize=true,WrapContents=false};line.Controls.Add(new Label(){AutoSize=true,Text=L("Skill ","技能 ")+(i+1)});var search=new TextBox(){Width=180,PlaceholderText=L("Skill name or ID","技能名称或 ID")};var choice=skills[i]=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDownList,Width=470,DropDownWidth=650,Enabled=opened.Pairs is not null};choice.FormattingEnabled=true;choice.Format+=(_,e)=>{if(e.ListItem is SkillPair pair)e.Value=pair.Id==0&&pair.Level==0?L("None (ID 0, level 0)","无（ID 0，等级 0）"):$"ID {pair.Id} / {L("level","等级")} {pair.Level} · "+names.GameLabel(GameCatalogKind.Skill,pair.Id);};
            void Filter(){SkillPair? selected=choice.SelectedItem as SkillPair??opened.Pairs?[ordinal];choice.BeginUpdate();choice.Items.Clear();foreach(var pair in editor.Domain.KnownSkillPairs.Where(p=>p==selected||names.Matches(GameCatalogKind.Skill,p.Id,search.Text)))choice.Items.Add(pair);if(selected is not null)choice.SelectedItem=selected;choice.EndUpdate();}
            search.TextChanged+=(_,_)=>Filter();Filter();choice.SelectedIndexChanged+=(_,_)=>{if(choice.SelectedItem is SkillPair pair)tip.SetToolTip(choice,names.Describe(GameCatalogKind.Skill,pair.Id));};if(choice.SelectedItem is SkillPair initial)tip.SetToolTip(choice,names.Describe(GameCatalogKind.Skill,initial.Id));line.Controls.AddRange([search,choice]);root.Controls.Add(line);}
            if(opened.PairIssue is not null)root.Controls.Add(new Label(){AutoSize=true,Text=L("Skill editing unavailable: ","技能编辑不可用：")+opened.PairIssue});}
        var actions=new FlowLayoutPanel(){AutoSize=true};var apply=new Button(){AutoSize=true,Text=L("Apply draft","应用草稿")};var cancel=new Button(){AutoSize=true,Text=L("Cancel","取消"),DialogResult=DialogResult.Cancel};actions.Controls.AddRange([apply,cancel]);actions.Dock=DockStyle.Fill;actions.Padding=new Padding(16,6,16,12);shell.Controls.Add(actions,0,1);CancelButton=cancel;
        apply.Click+=(_,_)=>{try{ApplyDraft();DialogResult=DialogResult.OK;Close();}catch(Exception e){MessageBox.Show(this,L("Draft was not applied. ","草稿未应用。")+e.Message,Text);}};WorkshopStyle.Apply(this);        void Fit(){int width=Math.Max(300,root.ClientSize.Width-root.Padding.Horizontal-28);root.SuspendLayout();foreach(Control control in root.Controls){if(control is Label label)label.MaximumSize=new(width,0);if(control is FlowLayoutPanel row&&row.Controls.OfType<ComboBox>().FirstOrDefault() is ComboBox combo){int used=row.Controls.Cast<Control>().Where(c=>c!=combo).Sum(c=>c.Width+c.Margin.Horizontal);combo.Width=Math.Max(160,width-used-combo.Margin.Horizontal);combo.DropDownWidth=750;row.AutoSize=false;row.Width=width;row.Height=row.Controls.Cast<Control>().Max(c=>c.Height+c.Margin.Vertical);}}root.AutoScrollPosition=Point.Empty;root.ResumeLayout();}root.SizeChanged+=(_,_)=>Fit();Shown+=(_,_)=>Fit();
    }
    internal void ClearDraft(){foreach(var c in jewels)c.SelectedItem=0u;}
    internal void ApplyDraft()=>editor.ApplyDomain(d=>d.ApplyEquipmentDraft(opened,opened.Decorations is null?null:jewels.Select(c=>(uint)c.SelectedItem!).ToArray(),opened.Pairs is null?null:skills.Select(c=>(SkillPair)c.SelectedItem!).ToArray()));
}
internal sealed class InventoryTransferForm : Form
{
    internal InventoryTransferForm(DirectoryEditor editor,int source)
    {
        string L(string e,string z)=>EquipmentDraftForm.L(e,z);var d=editor.Domain!;var item=d.Inventory().Single(i=>i.Index==source);if(item.Id is not uint id||item.Quantity is not >0)throw new InvalidOperationException(L("Select a nonempty record.","请选择非空记录。"));Text=L("Split / move / merge","拆分 / 移动 / 合并");Size=new(750,420);MinimumSize=new(680,400);Font=new("Microsoft YaHei UI",9.5f);StartPosition=FormStartPosition.CenterParent;
        var root=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new(16),AutoScroll=true};Controls.Add(root);root.Controls.Add(new Label(){AutoSize=true,MaximumSize=new(680,0),Text=$"{L("Source record","来源记录")} {source} · ID {id}\n{L("Original observed stack bound (not a game maximum)","原始观察堆叠界限（并非游戏上限）")}: {d.OriginalStackCeiling(id)}"});
        var target=new ComboBox(){Width=620,DropDownStyle=ComboBoxStyle.DropDownList};foreach(var row in d.Inventory().Where(r=>r.Index!=source&&(r.Id==id&&r.Quantity>0||r.Id==DomainEditor.EmptyItemId&&r.Quantity==0)))target.Items.Add(row);target.FormattingEnabled=true;target.Format+=(_,e)=>{if(e.ListItem is InventoryItem r)e.Value=$"{L("Record","记录")} {r.Index} · ID {r.Id} · {L("Quantity","数量")} {r.Quantity}";};if(target.Items.Count>0)target.SelectedIndex=0;root.Controls.Add(target);var next=new Button(){AutoSize=true,Text=L("Next empty record","下一个空记录")};next.Click+=(_,_)=>{int index=d.NextEmptyInventoryRecord();foreach(var row in target.Items.Cast<InventoryItem>())if(row.Index==index)target.SelectedItem=row;};root.Controls.Add(next);var amount=new NumericUpDown(){Minimum=1,Maximum=item.Quantity.Value,Value=1,Width=180};root.Controls.Add(new Label(){AutoSize=true,Text=L("Transfer quantity","转移数量")});root.Controls.Add(amount);var apply=new Button(){AutoSize=true,Text=L("Confirm transfer","确认转移"),Enabled=target.Items.Count>0};var buttons=new FlowLayoutPanel(){AutoSize=true};var cancel=new Button(){AutoSize=true,Text=L("Cancel","取消"),DialogResult=DialogResult.Cancel};CancelButton=cancel;buttons.Controls.AddRange([apply,cancel]);root.Controls.Add(buttons);root.SizeChanged+=(_,_)=>target.Width=Math.Max(300,root.ClientSize.Width-48);apply.Click+=(_,_)=>{try{editor.ApplyDomain(model=>model.TransferItem(source,((InventoryItem)target.SelectedItem!).Index,(int)amount.Value));DialogResult=DialogResult.OK;Close();}catch(Exception e){MessageBox.Show(this,L("Transfer was not applied. ","转移未应用。")+e.Message,Text);}};WorkshopStyle.Apply(this);
    }
}
